import hashlib
import json
import os
from pathlib import Path
import shutil
import subprocess
import sys
import time
import uuid


def wait_for(operation, description):
    deadline = time.monotonic_ns() + 10_000_000_000
    while True:
        value = operation()
        if value:
            return value
        if time.monotonic_ns() >= deadline:
            raise AssertionError('Missing observation: ' + description)
        time.sleep(0.01)


def populated(group):
    return 'populated 1' in (group / 'cgroup.events').read_text()


def main():
    work = Path(sys.argv[1]).resolve()
    java = Path(sys.argv[2]).resolve()
    evidence = json.loads((work / 'evidence.json').read_text())
    source = evidence['proof_files']['LinuxProcessTree.java']['text']
    expected = evidence['proof_files']['LinuxProcessTree.java']['sha256']
    assert hashlib.sha256(source.encode()).hexdigest() == expected
    (work / 'LinuxProcessTree.java').write_text(source)
    (work / 'workload.py').write_text(evidence['external_drivers']['workload.py']['text'])
    (work / 'SupervisorPause.java').write_text('''
import java.nio.file.*;
import java.nio.file.attribute.PosixFilePermissions;
import java.util.*;
public final class SupervisorPause {
    public static void main(String[] args) throws Exception {
        Path classes = Path.of(args[0]);
        Path work = Path.of(args[1]);
        var launch = new LinuxProcessTree.Launch(Path.of(args[2]), work,
            Path.of(System.getProperty("java.home"), "bin", "java"), classes,
            List.of("/usr/bin/python3", Path.of(args[3]).toString(), "root",
                work.resolve("root.properties").toString(), work.resolve("leaf.properties").toString()),
            Map.of("OWNER_GATE_TOKEN", "supervisor-death-probe"), work, 1001, 1001);
        try (var tree = LinuxProcessTree.prepare(launch)) {
            if (args[4].equals("released")) {
                tree.release();
                if (tree.awaitRootExit() != 7) throw new AssertionError("Root status differs");
            }
            if (args[4].equals("unpublished") == false)
                Files.writeString(work.resolve("supervisor.ready"), tree.group().toString());
            System.in.read();
        }
    }
}
''')
    classes = work / 'classes'
    classes.mkdir()
    subprocess.run([str(java.with_name('javac')), '--release', '27', '-d', str(classes),
        str(work / 'LinuxProcessTree.java'), str(work / 'SupervisorPause.java')], check=True)
    membership = Path('/proc/self/cgroup').read_text().strip().split('::', 1)[1]
    ancestor = Path('/sys/fs/cgroup') / membership.lstrip('/')
    parent = ancestor / ('supervisor-recovery-' + uuid.uuid4().hex)
    parent.mkdir()
    receipts = []
    try:
        for phase in ('prepared', 'released', 'unpublished'):
            case = work / phase
            case.mkdir(mode=0o777)
            case.chmod(0o777)
            with open(case / 'supervisor.log', 'wb') as output:
                child = subprocess.Popen([str(java), '--enable-native-access=ALL-UNNAMED',
                    '-Djava.io.tmpdir=' + str(work), '-cp', str(classes), 'SupervisorPause',
                    str(classes), str(case), str(parent), str(work / 'workload.py'), phase],
                    stdin=subprocess.PIPE, stdout=output, stderr=subprocess.STDOUT)
                try:
                    if phase == 'unpublished':
                        group = wait_for(lambda: next((g for g in parent.iterdir()
                            if g.is_dir() and populated(g)), None), 'unpublished populated group')
                        assert (case / 'supervisor.ready').exists() is False
                    else:
                        ready = case / 'supervisor.ready'
                        wait_for(ready.exists, 'supervisor readiness')
                        group = Path(ready.read_text())
                    if phase == 'released':
                        wait_for((case / 'leaf.properties').exists, 'detached descendant')
                    before = (group / 'cgroup.procs').read_text().split()
                    assert len(before) > 0
                    child.kill()
                    status = child.wait(timeout=10)
                    assert status == -9
                    assert populated(parent), 'Supervisor death unexpectedly completed workload'
                    after_death = (group / 'cgroup.procs').read_text().split()
                    assert len(after_death) > 0
                    (parent / 'cgroup.kill').write_text('1')
                    wait_for(lambda: populated(parent) is False, 'parent empty after recovery')
                    wait_for(lambda: all(Path('/proc', pid).exists() is False for pid in set(before + after_death)),
                        'killed process identities reaped by host')
                    for subgroup in tuple(parent.iterdir()):
                        if subgroup.is_dir():
                            subgroup.rmdir()
                    receipt = {'phase': phase, 'supervisor_exit': status,
                        'members_before': before, 'members_after_supervisor_death': after_death,
                        'recovery_parent_populated': False, 'owned_groups_remaining': [],
                        'readiness_published': (case / 'supervisor.ready').exists()}
                    receipts.append(receipt)
                    print(json.dumps(receipt), flush=True)
                finally:
                    if child.poll() is None:
                        child.kill()
                        child.wait()
                    child.stdin.close()
                    (parent / 'cgroup.kill').write_text('1')
                    wait_for(lambda: populated(parent) is False, 'failure cleanup empty parent')
                    for subgroup in tuple(parent.iterdir()):
                        if subgroup.is_dir():
                            subgroup.rmdir()
        (work / 'results.json').write_text(json.dumps({'outcome': 'passed',
            'source_sha256': expected, 'cases': receipts}, indent=2) + '\n')
    finally:
        (parent / 'cgroup.kill').write_text('1')
        wait_for(lambda: populated(parent) is False, 'final parent cleanup')
        for subgroup in tuple(parent.iterdir()):
            if subgroup.is_dir():
                subgroup.rmdir()
        parent.rmdir()
    assert parent.exists() is False
    print('supervisor_recovery=passed', flush=True)


if __name__ == '__main__':
    main()

