import json
import os
from pathlib import Path
import signal
import subprocess
import sys
import uuid

from probe import populated, wait_for


def main():
    work = Path(sys.argv[1]).resolve()
    java = Path(sys.argv[2]).resolve()
    source = work / 'InheritanceGate.java'
    source.write_text('''
import java.nio.file.*;
public final class InheritanceGate {
    public static void main(String[] args) throws Exception {
        if (args[0].equals("--child")) {
            Thread.sleep(20000);
            return;
        }
        Path parent = Path.of(args[0]);
        Path work = Path.of(args[1]);
        if (args[2].equals("inside"))
            Files.writeString(parent.resolve("cgroup.procs"), Long.toString(ProcessHandle.current().pid()));
        Process child = new ProcessBuilder(Path.of(System.getProperty("java.home"), "bin", "java").toString(),
            "-Djava.io.tmpdir=" + work, "-cp", args[3], "InheritanceGate", "--child").start();
        Files.writeString(work.resolve("child.pid"), Long.toString(child.pid()));
        System.in.read();
    }
}
''')
    classes = work / 'inheritance-classes'
    classes.mkdir()
    subprocess.run([str(java.with_name('javac')), '--release', '27', '-d', str(classes), str(source)], check=True)
    membership = Path('/proc/self/cgroup').read_text().strip().split('::', 1)[1]
    ancestor = Path('/sys/fs/cgroup') / membership.lstrip('/')
    receipts = []
    for mode in ('outside', 'inside'):
        parent = ancestor / ('inheritance-recovery-' + uuid.uuid4().hex)
        parent.mkdir()
        case = work / ('inheritance-' + mode)
        case.mkdir()
        child_pid = None
        supervisor = subprocess.Popen([str(java), '-Djava.io.tmpdir=' + str(work), '-cp',
            str(classes), 'InheritanceGate', str(parent), str(case), mode, str(classes)],
            stdin=subprocess.PIPE)
        try:
            wait_for((case / 'child.pid').exists, 'inherited helper identity')
            child_pid = int((case / 'child.pid').read_text())
            child_group = Path('/proc', str(child_pid), 'cgroup').read_text().strip()
            contained = child_group.endswith('/' + parent.name)
            assert contained == (mode == 'inside')
            supervisor.kill()
            assert supervisor.wait(timeout=10) == -9
            assert Path('/proc', str(child_pid)).exists()
            (parent / 'cgroup.kill').write_text('1')
            if mode == 'inside':
                wait_for(lambda: Path('/proc', str(child_pid)).exists() is False, 'inherited child recovered')
                recovered = True
            else:
                assert Path('/proc', str(child_pid)).exists()
                recovered = False
            receipt = {'supervisor_placement': mode, 'helper_pid': child_pid,
                'helper_membership': child_group, 'inherited_controller_parent': contained,
                'controller_parent_kill_recovered_helper': recovered}
            receipts.append(receipt)
            print(json.dumps(receipt), flush=True)
        finally:
            if supervisor.poll() is None:
                supervisor.kill()
                supervisor.wait()
            supervisor.stdin.close()
            (parent / 'cgroup.kill').write_text('1')
            if child_pid is not None and Path('/proc', str(child_pid)).exists():
                os.kill(child_pid, signal.SIGKILL)
                wait_for(lambda: Path('/proc', str(child_pid)).exists() is False, 'control helper cleanup')
            wait_for(lambda: populated(parent) is False, 'inheritance parent cleanup')
            parent.rmdir()
    (work / 'inheritance-results.json').write_text(json.dumps({'outcome': 'passed', 'cases': receipts}, indent=2) + '\n')
    print('inheritance_recovery=passed', flush=True)


if __name__ == '__main__':
    main()

